import {buildUniqueAnchor, slugifyAnchor} from './anchor';
import {
  ExtractedTextRun,
  RulesBlock,
  RulesDocument,
  RulesParseMetadata,
  RulesSection,
  TocEntry,
} from './types';

const HEADING_L1_SIZE = 16;
const HEADING_L2_SIZE = 13;

function isTwoColumnPage(pageItems: ExtractedTextRun[]): boolean {
  if (pageItems.length < 6) {
    return false;
  }

  let minX = Infinity;
  let maxX = -Infinity;
  for (const item of pageItems) {
    if (item.x < minX) {
      minX = item.x;
    }
    if (item.x > maxX) {
      maxX = item.x;
    }
  }

  const spread = maxX - minX;
  if (spread < 140) {
    return false;
  }

  const midX = minX + spread / 2;
  const leftCount = pageItems.filter(item => item.x < midX).length;
  const rightCount = pageItems.length - leftCount;

  return leftCount >= 3 && rightCount >= 3;
}

function sortItemsForReadingOrder(items: ExtractedTextRun[]): ExtractedTextRun[] {
  const byPage: Record<number, ExtractedTextRun[]> = {};

  for (const item of items) {
    if (!byPage[item.page]) {
      byPage[item.page] = [];
    }
    byPage[item.page].push(item);
  }

  const pages = Object.keys(byPage)
    .map(value => Number(value))
    .sort((a, b) => a - b);
  const sorted: ExtractedTextRun[] = [];

  for (const page of pages) {
    const pageItems = byPage[page];
    if (isTwoColumnPage(pageItems)) {
      let minX = Infinity;
      let maxX = -Infinity;
      for (const item of pageItems) {
        if (item.x < minX) {
          minX = item.x;
        }
        if (item.x > maxX) {
          maxX = item.x;
        }
      }
      const midX = minX + (maxX - minX) / 2;

      const left = pageItems
        .filter(item => item.x < midX)
        .sort((a, b) => a.y - b.y || a.x - b.x);
      const right = pageItems
        .filter(item => item.x >= midX)
        .sort((a, b) => a.y - b.y || a.x - b.x);

      sorted.push(...left, ...right);
      continue;
    }

    sorted.push(...pageItems.sort((a, b) => a.y - b.y || a.x - b.x));
  }

  return sorted;
}

function inferHeadingLevel(item: ExtractedTextRun): number {
  const size = item.fontSize || 0;
  if (size >= HEADING_L1_SIZE) {
    return 1;
  }
  if (size >= HEADING_L2_SIZE) {
    return 2;
  }
  return 0;
}

function createParagraphBlock(item: ExtractedTextRun): RulesBlock {
  return {
    type: 'paragraph',
    textRuns: [
      {
        text: item.text,
        href: item.internalHref ? `#${slugifyAnchor(item.internalHref)}` : undefined,
      },
    ],
  };
}

function createHeadingSection(
  item: ExtractedTextRun,
  anchorCounts: Record<string, number>,
): RulesSection {
  const anchor = buildUniqueAnchor(item.text, anchorCounts);
  return {
    id: anchor,
    title: item.text,
    level: inferHeadingLevel(item),
    anchor,
    pageRef: item.page,
    blocks: [
      {
        type: 'heading',
        textRuns: [{text: item.text}],
      },
    ],
  };
}

function createFallbackSection(anchorCounts: Record<string, number>): RulesSection {
  const fallbackTitle = 'Introduction';
  const anchor = buildUniqueAnchor(fallbackTitle, anchorCounts);
  return {
    id: anchor,
    title: fallbackTitle,
    level: 1,
    anchor,
    pageRef: 1,
    blocks: [],
  };
}

function buildToc(sections: RulesSection[]): TocEntry[] {
  return sections.map((section, index) => ({
    title: section.title,
    anchor: section.anchor,
    level: section.level,
    order: index,
  }));
}

export function parseExtractedTextRuns(
  items: ExtractedTextRun[],
  metadata: RulesParseMetadata,
): RulesDocument {
  const sorted = sortItemsForReadingOrder(items);
  const anchorCounts: Record<string, number> = {};
  const sections: RulesSection[] = [];

  let currentSection: RulesSection | null = null;
  for (const item of sorted) {
    const trimmedText = item.text.trim();
    if (!trimmedText) {
      continue;
    }

    const normalizedItem: ExtractedTextRun = {
      ...item,
      text: trimmedText,
    };
    const headingLevel = inferHeadingLevel(normalizedItem);

    if (headingLevel > 0) {
      currentSection = createHeadingSection(normalizedItem, anchorCounts);
      sections.push(currentSection);
      continue;
    }

    if (!currentSection) {
      currentSection = createFallbackSection(anchorCounts);
      sections.push(currentSection);
    }

    currentSection.blocks.push(createParagraphBlock(normalizedItem));
  }

  return {
    version: metadata.version,
    sourceUrl: metadata.sourceUrl,
    sourceSha256: metadata.sourceSha256,
    generatedAt: metadata.generatedAt,
    sections,
    toc: buildToc(sections),
  };
}
